question:
I have a `flatten_config` utility that flattens nested dictionaries. I’m adding a `max_depth` parameter, but I’m not sure whether my implementation matches the intended semantics. The existing tests pass, and I want the depth-limited behavior to be consistent and documented. Can you update the implementation so it matches the intended `max_depth` convention and all tests pass?

```python
from typing import Dict, Any


def flatten_config(config: Dict[str, Any], separator: str = ".", max_depth: int = -1) -> Dict[str, Any]:
    """Flatten a nested config dictionary.

    Args:
        config: Nested dictionary to flatten.
        separator: Key separator string.
        max_depth: Maximum number of nesting levels to expand.
                   -1 means flatten fully.
                   0 means do not flatten.
                   1 means expand one level, etc.

    Returns:
        Flattened dictionary.
    """
    def _flatten(obj, parent_key, current_depth):
        items = {}
        if isinstance(obj, dict) and (max_depth == -1 or current_depth < max_depth):
            for k, v in obj.items():
                new_key = f"{parent_key}{separator}{k}" if parent_key else k
                items.update(_flatten(v, new_key, current_depth + 1))
        else:
            items[parent_key] = obj
        return items

    return _flatten(config, "", 0)


# --- Existing tests (all passing) ---

def test_flat_config():
    cfg = {"host": "localhost", "port": 8080}
    assert flatten_config(cfg) == {"host": "localhost", "port": 8080}


def test_nested_config():
    cfg = {"db": {"host": "localhost", "port": 5432}}
    assert flatten_config(cfg) == {"db.host": "localhost", "db.port": 5432}


def test_deeply_nested():
    cfg = {"a": {"b": {"c": 42}}}
    assert flatten_config(cfg) == {"a.b.c": 42}


def test_custom_separator():
    cfg = {"db": {"host": "localhost"}}
    assert flatten_config(cfg, separator="__") == {"db__host": "localhost"}


# --- New depth tests ---

def test_max_depth_1_expands_one_level():
    """With max_depth=1, expand one level and keep deeper dicts intact."""
    cfg = {"a": {"b": {"c": 42}}}
    result = flatten_config(cfg, max_depth=1)
    assert result == {"a.b": {"c": 42}}


def test_max_depth_0_keeps_structure_intact():
    """With max_depth=0, no flattening should happen."""
    cfg = {"a": {"b": {"c": 42}}}
    result = flatten_config(cfg, max_depth=0)
    assert result == {"a": {"b": {"c": 42}}}
```

Can you fix the implementation so it matches the documented `max_depth` behavior and all tests pass?

A user is debugging a Python URL query string parser. The implementation appears mostly correct, but one of the tests may reveal a subtle inconsistency in how repeated keys and URL decoding are handled. Can you review the code and point out what, if anything, is wrong?

```python
from typing import Dict, List, Union
from urllib.parse import unquote_plus

def parse_query_string(query: str) -> Dict[str, Union[str, List[str]]]:
    """Parse a URL query string into a dictionary.

    Rules:
    - Parameters are separated by '&'
    - Key-value pairs are separated by '='
    - Values are URL-decoded (percent-encoding and '+' as space)
    - If a key appears multiple times, its value is a list of all values
    - If a key appears once, its value is a plain string
    - Keys with no '=' sign are stored with empty string value
    - Empty string input returns empty dict
    """
    if not query:
        return {}

    result: Dict[str, Union[str, List[str]]] = {}

    for pair in query.split('&'):
        if '=' in pair:
            key, _, value = pair.partition('=')
        else:
            key, value = pair, ''

        key = unquote_plus(key)
        value = unquote_plus(value)

        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(value)
            else:
                result[key] = [existing, value]
        else:
            result[key] = value

    return result
```

